export function getModuleSettingsBasePath(path: string): string | undefined {
  for (const settingsPath of Object.keys(MODULE_SETTINGS_BY_PATH)) {
    if (path === settingsPath || path.startsWith(`${settingsPath}/`)) return settingsPath;
  }
  return undefined;
}

export function getModuleSettingsCatalog(path: string): ModuleSettingCatalogHub | undefined {
  const base = getModuleSettingsBasePath(path);
  return base ? MODULE_SETTINGS_BY_PATH[base] : undefined;
}

export function groupCatalogItemsByCategory(items: ModuleSettingCatalogItem[]): ModuleSettingCatalogGroup[] {
  const order: string[] = [];
  const map = new Map<string, ModuleSettingCatalogItem[]>();
  for (const item of items) {
    if (!map.has(item.groupKey)) {
      map.set(item.groupKey, []);
      order.push(item.groupKey);
    }
    map.get(item.groupKey)!.push(item);
  }
  return order.map((groupKey) => {
    const groupItems = map.get(groupKey)!;
    return { groupKey, groupTitle: groupItems[0]?.groupTitle ?? groupKey, items: groupItems };
  });
}
